/**
 * E2E: Steward daemon as the desktop app's inference backend.
 *
 * The full chain is exercised for real: Electron app → `hermes serve`
 * (python gateway, dev checkout) → OpenAI-compatible provider → Steward
 * daemon `/omp/v1/chat/completions` (wire port) → agent runtime → live
 * model. No mock inference server; the daemon IS the backend.
 *
 * Prerequisites: `npm run build` (dist/) and the Steward daemon running
 * with its wire port persisted at %USERPROFILE%/.steward/wire-port.
 */

import * as fs from 'node:fs'
import * as os from 'node:os'
import * as path from 'node:path'

import { expect, test } from './test'

import { buildAppEnv, createSandbox, launchDesktop, waitForAppReady } from './fixtures'

const WIRE_PORT_FILE = path.join(os.homedir(), '.steward', 'wire-port')

let fixture: Awaited<ReturnType<typeof setupStewardBackend>> | null = null

/** Sandbox wired to the live Steward daemon instead of a mock server. */
async function setupStewardBackend() {
  const port = fs.readFileSync(WIRE_PORT_FILE, 'utf8').trim()
  if (!/^\d+$/.test(port)) {
    throw new Error(`Steward wire port unreadable at ${WIRE_PORT_FILE}: ${port}`)
  }

  const sandbox = createSandbox('steward')
  const configPath = path.join(sandbox.hermesHome, 'config.yaml')
  // Same provider shape as writeMockProviderConfig, pointed at the daemon.
  // api_mode chat_completions + any key (the daemon bridge ignores auth).
  fs.writeFileSync(
    configPath,
    `# Auto-generated by E2E test fixtures — Steward daemon backend
model:
  default: steward-local
  provider: steward
providers:
  steward:
    api: http://127.0.0.1:${port}/omp/v1
    name: Steward
    api_mode: chat_completions
    key_env: STEWARD_API_KEY
    models:
      glm-5.3-flash: {}
    context_length: 32768
auxiliary:
  title_generation:
    enabled: false
approvals:
  mode: "off"
`,
    'utf8',
  )
  fs.writeFileSync(path.join(sandbox.hermesHome, '.env'), 'STEWARD_API_KEY=steward-local-e2e\n', 'utf8')

  const env = buildAppEnv(sandbox)
  const { app, page } = await launchDesktop(env)
  await waitForAppReady({ app, page, sandbox } as never, 120_000)

  return {
    app,
    page,
    sandbox,
    cleanup: async () => {
      await app.close().catch(() => undefined)
      sandbox.cleanup()
    },
  }
}

test.beforeAll(async () => {
  fixture = await setupStewardBackend()
})

test.afterAll(async () => {
  await fixture?.cleanup()
  fixture = null
})

test.describe('desktop app against live Steward daemon', () => {
  test('boots past onboarding into the chat UI', async () => {
    const page = fixture!.page

    // Onboarding must NOT gate the session: a provider is preconfigured.
    // (waitForOnboarding matches "provider|Choose|API key|Sign in" text.)
    const composer = page.locator('[contenteditable="true"]').first()
    await composer.waitFor({ state: 'visible', timeout: 30_000 })
  })

  test('send a prompt and stream the Steward answer into the transcript', async ({ }, testInfo) => {
    test.setTimeout(120_000)
    const page = fixture!.page

    const marker = `STEWARD-DESKTOP-E2E-${Date.now()}`
    const composer = page.locator('[contenteditable="true"]').first()
    await composer.click()
    await composer.type(`Reply with exactly: ${marker}`, { delay: 15 })
    await page.keyboard.press('Enter')

    // User message lands in the transcript.
    await page.waitForFunction(
      (m) => (document.body?.textContent ?? '').includes(m),
      marker,
      { timeout: 20_000 },
    )

    // The daemon's answer streams back through gateway → provider → SSE.
    // The live model echoes the marker in its reply.
    await page.waitForFunction(
      (m) => (document.body?.textContent ?? '').split(m).length > 2,
      marker,
      { timeout: 90_000 },
    )
  })
})
